-- GENERATED by `wfj generate` from data/quest/quest-0096.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [96016] = { "Le armi della tempesta", "Consegna l'Eye of the Tempest a Bath'rah l'osservatore dei venti, nelle ⟦Alterac Mountains=Montagne d'Alterac⟧.", "Hai fatto un buon lavoro, e vedo che non stai più nella pelle per la ricompensa. Mi spiace dirtelo, ma non sono proprio un nano di molti averi.\n\n<Veyric indica con un ampio gesto il luogo sperduto in cui si trova.>\n\nFacciamo così, però. Ho sentito che un troll chiamato l'osservatore dei venti vive tra le ⟦Alterac Mountains=Montagne d'Alterac⟧. È anche lui un potente sciamano, ed esperto di elementali della tempesta. Se gli porti quel nucleo elementale, scommetto che può forgiarti un'arma degna della tua vittoria.", nil, nil, 0x578d0b90, 0x5da19497, 0x67a5ea2f, nil, nil, "...mm" },
  [96031] = { "Campeggio 101: Conciatura", "Parla con ⟦Gretta Finespindle=Gretta Filofino⟧ a ⟦Ironforge=Forgiardente⟧ per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Così ora lavori il cuoio. Buon per te, {class}. Mi sa che conosco qualcuno che può insegnarti a fabbricare una tenda che ti terrà al fresco nei giorni caldi e all'asciutto in quelli di pioggia.\n\nCon una buona tenda sopra la testa, avrai tutto il riposo che ti serve per restare in forma durante i tuoi viaggi.", nil, nil, 0x40d05936, 0x444c023e, 0x86e620e9, nil, nil, "...mm" },
  [96044] = { "Campeggio 101: Forgiatura", "Parla con ⟦Tognus Flintfire=Tognus Fiammaselce⟧ a Kharanos per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Dunque ti sei dat<o/a> alla Forgiatura. Ottima scelta, se vuoi che le tue lame non perdano mai il filo.\n\nMi sa che conosco qualcuno che può aiutarti, insegnandoti a fabbricare una Sharpening Wheel. Tirane fuori una al tuo accampamento e tutti i guerrieri e i ladri dei dintorni faranno la fila per affilare le loro armi.", nil, nil, 0x16979ea3, 0xcccec145, 0x469a706e, nil, nil, "...mm" },
  [96045] = { "Campeggio 101: Alchimia", "Parla con Vosur Brakthel a ⟦Ironforge=Forgiardente⟧ per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Ora che ti sei dedicat<o/a> all'Alchimia, posso anche insegnarti a costruire un Mana Well per il tuo accampamento, una volta che avrai imparato un po' il mestiere. Costruiscine uno, e tutti i guaritori e quelli che lanciano incantesimi accorreranno per un sorso rinfrescante.", nil, nil, 0x32f4ba12, 0xfd210ba1, 0xd857517b, nil, nil, "...mm" },
  [96046] = { "Campeggio 101: Estrazione", "Parla con ⟦Yarr Hammerstone=Yarr Sassomartello⟧ a Kharanos per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "L'Estrazione non sarà il mestiere più affascinante, ma è un lavoro onesto e una bella professione da esplorare.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una Lodestone per il tuo accampamento. Costruiscine una e chiunque voglia menare la spada non vedrà l'ora di radunarsi attorno al tuo fuoco per assorbire quella \"grinta\" in più che può dare alla sua abilità in combattimento.", nil, nil, 0xa8fe12f3, 0xc44564fc, 0x8ef0fff6, nil, nil, "...mm" },
  [96047] = { "Campeggio 101: ⟦First Aid=Primo Soccorso⟧", "Parla con Thamner Pol a Kharanos per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Quindi ti sei dat<o/a> al ⟦First Aid=Primo Soccorso⟧? È un'attività onorevole... e pragmatica per <un/una> {class}.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un First Aid Kit per il tuo accampamento. Nella vita d'avventura le ferite sono una realtà, e offrire un po' di cure tanto necessarie al tuo accampamento potrebbe persino salvare delle vite.", nil, nil, 0x6e7c255b, 0xdf8f53b4, 0x32ff3188, nil, nil, "...mm" },
  [96050] = { "Campeggio 101: Pesca", "Parla con Paxton Ganter vicino al ⟦Iceflow Lake=Lago di Ghiacciospesso⟧, a Dun Morogh, per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Forse non lo diresti, ma la tua abilità nella Pesca può davvero tornare utile all'accampamento.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Fish Bowl per il tuo accampamento. Puoi usare questo arredo per portare un po' di gioia a te e ai tuoi compagni d'avventura. Un avventuriero felice è un avventuriero forte, e di sicuro le tue capacità in combattimento lo dimostreranno.", nil, "Ecco fatto: ora puoi fabbricare un Fish Bowl tutto tuo. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xe0c1c700, 0x475dee95, 0x1bcf05fd, nil, 0x54727538, "...m." },
  [96055] = { "Campeggio 101: Erbalismo", "Parla con ⟦Reyna Stonebranch=Reyna Brancapietra⟧ a ⟦Ironforge=Forgiardente⟧ per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Mi pare che tu abbia acquisito una certa abilità nell'Erbalismo. Raccogliere fiori non serve solo a perdere tempo, sai. Può essere utile... e redditizio.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un'Incense Candle per il tuo accampamento. Il morale alto è fondamentale per tenere in battaglia guaritori e lanciatori di incantesimi, e un'Incense Candle può dare una spinta che chi usa la magia apprezzerà di certo.", nil, "Ecco fatto: ora puoi fabbricare un'Incense Candle tutta tua. Alla gente non piace granché vedere accampamenti montati in centro città, quindi dovrai andartene in mezzo alla natura selvaggia se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di montare il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti fare un salto da qualcuno che ti istruisca nelle arti culinarie, per impararne le basi.", 0xd7cde71c, 0x8a8b95de, 0xe0048777, nil, 0x52608ebe, "...m." },
  [96056] = { "Campeggio 101: Scuoiatura", "Parla con ⟦Balthus Stoneflayer=Balthus Sventrapietra⟧ a ⟦Ironforge=Forgiardente⟧ per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Saper ricavare con abilità pelli e cuoi dalle bestie abbattute è una delle capacità più preziose che un avventuriero possa avere.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare una Camp Chair per il tuo accampamento. A volte è importante concedersi un po' di riposo, e puoi usare alcune delle pelli che hai raccolto per farti una sedia comoda su cui sederti. Un po' di relax può aiutarti a restare in piena forma e a colpire dove conta la prossima volta che ti ritroverai in una zuffa.", nil, nil, 0x14236b38, 0x9b6727a8, 0x1755b1ba, nil, nil, "...mm" },
  [96057] = { "Campeggio 101: Sartoria", "Parla con Uthrar Threx a ⟦Ironforge=Forgiardente⟧ per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare un Faction Banner per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, "Ecco fatto: ora puoi costruire il tuo Rallying Banner personale. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo al paese, quindi dovrai andare nelle terre selvagge se vuoi provarlo.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco da campo. Te ne servirà uno prima di allestire il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, potresti rivolgerti a qualcuno che possa istruirti nelle arti culinarie per imparare le basi.", 0xde7f398c, 0xf651cfe5, 0x49663bd1, nil, 0x8e312c30, "...m." },
  [96058] = { "Campeggio 101: Ingegneria", "Parla con ⟦Bronk Guzzlegear=Bronk Acquavite⟧ a Kharanos per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Gli ingegneri come te sanno inventarsi ogni sorta di congegni, robot e bombe, per divertimento e per profitto.\n\nMi sa che conosco qualcuno che può insegnarti a fabbricare un Reagent Bot per il tuo accampamento. Questo utile automa può aiutarti a restare ben rifornit<o/a>, così tu e i tuoi alleati non resterete mai senza i materiali che servono ad alimentare i vostri incantesimi.", nil, nil, 0x1cb4025b, 0x1d43c051, 0x549b28c0, nil, nil, "...mm" },
  [96059] = { "Campeggio 101: Incantamento", "Parla con ⟦Thonys Pillarstone=Thonys Pernoforte⟧ a ⟦Ironforge=Forgiardente⟧ per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "Ora che hai intrapreso il cammino dell'incantatore, credo di poterti insegnare a costruire un Enchanted Lute per il tuo accampamento, una volta che avrai imparato il mestiere.\n\nÈ davvero importante trovare uno svago nei momenti di riposo, e questo pizzico di magia può aiutarti a essere <pronto/pronta> ad affrontare ogni sorta di sfida quando riprenderai la vecchia strada polverosa.", nil, nil, 0x2e9b8c15, 0xa6eed0e9, 0x4457b10b, nil, nil, "...mm" },
  [96101] = { "La vita all'aria aperta", "Siediti vicino al Raan's Basic Campfire e attendi di ricevere il beneficio Boosted Rest.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", "Possedere le abilità necessarie per sopravvivere all'aperto è fondamentale. Un avventuriero ben riposato e ben preparato ha molte più probabilità di sopravvivere a questo stile di vita.", "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0xeb724be6, 0xb221e6cb, 0x452722a2, 0x2eacf33d, "....." },
  [96102] = { "Campeggio 101: Sartoria", "Parla con Snang a Orgrimmar per imparare a costruire un oggetto da accampamento per la tua professione, una volta dimostrata la tua competenza nell'abilità.", "La Sartoria è un mestiere sorprendentemente valido su cui investire, e di certo ti servirà bene.\n\nConosco qualcuno che può insegnarti a fabbricare un Faction Banner per il tuo accampamento, se hai l'abilità necessaria. Ispirazione e morale sono fondamentali per vincere su qualsiasi campo di battaglia, e uno stendardo che ispira può fare molto per tenerti carico di energie.", nil, nil, 0xde7f398c, 0xb3ef6f61, 0x49663bd1, nil, nil, "...mm" },
  [96130] = { nil, "Sconfiggi Chakuyak e riporta la sua pelliccia.", "Tra i lupi della prateria che cacciano sulle colline qui vicino c'è una lupa particolarmente aggressiva. Abbiamo preso a chiamarla Chakuyak. È diventata una minaccia per i viaggiatori che arrivano da lontano.\n\nSi aggira tra gli alberi a ovest del ⟦Stonebull Lake=Lago Toro di Pietra⟧, spostandosi da un boschetto all'altro.\n\nPoni fine a questa minaccia e portami la sua pelliccia, e canterò le tue lodi al capo. Ma fai attenzione: è pericolosa! Potresti incontrare altri cacciatori sulle sue tracce, e forse potreste lavorare in squadra.", "Hai trovato la grossa lupa?", "Togliere la vita a una creatura così bella è un evento triste, ma era necessario per la sicurezza della nostra gente. Mi assicurerò che la pelliccia non vada sprecata. Grazie.", 0x5e7713ac, 0x243d382f, 0x76d59655, 0xf8c970d1, 0x599fc946, "e...." },
  [96135] = { "Ascolta il mio richiamo", "Usa i totem distorti per porre fine al rituale dei verrospini.", "Bleah, solo a stare vicino a questi maledetti totem mi vengono i brividi... ma è un bene. Tutta questa corruzione distorta è proprio quello che ci serve per evocare gli elementali dei verrospini.\n\nVa' a ⟦Thousand Needles=Millepicchi⟧ e trova un punto adatto per le tue difese. Le pozze di vapore dovrebbero andar bene: sono ricche di fuoco, terra, acqua e aria insieme. Piazza questi totem e preparati a combattere. I ⟦Razormane=Chiomaguzza⟧ non prenderanno affatto bene la tua interferenza.", nil, nil, 0xb87aaede, 0x5eafbe6d, 0x93cfea2b, nil, nil, "...mm" },
  [96136] = { "Il richiamo dell'aria", "Trova ⟦Prate Cloudseer=Prate Scruta Nubi⟧ a ⟦Thousand Needles=Millepicchi⟧.", "Come avrai senz'altro sperimentato di persona, gli elementi di Azeroth sono diversi da quelli di Zephras. Una cosa è incanalare le forze della natura nei piani elementali, tutt'altra è farlo quaggiù, nel fango.\n\nPotrei concederti il tuo totem dell'aria, ma credo che ti gioverebbe di più incontrare chi addestra gli altri iniziati legati alla terra. Che ne dici, {name}?", nil, nil, 0x8f4acf86, 0x7a57cbe0, 0x94a7ee28, nil, nil, "...mm" },
  [96137] = { "Il pugnale di Ira", "Sconfiggi $N1 Young Black Ravager e $N2 Black Ravager, poi torna da ⟦Sirra Von'Indi=Sirra Von'indi⟧ a ⟦Darkshire=Borgoscuro⟧ per saperne di più.", "Un piccolo pugnale appartenuto a Ira, guardaboschi autoproclamata, che proteggeva le foreste impedendo alle bestie che le abitavano di attaccare i viaggiatori.\n\nDato che lo spirito di Ira vaga ancora per i boschi, forse la sua questione in sospeso era sterminare i worg che continuano a mietere vittime in tutta la foresta.", nil, nil, 0x26c52f95, 0x8b815c85, 0x2af9a1e7, nil, nil, "...mm" },
  [96138] = { "L'arco di Merrick", "Sconfiggi $N1 Splinter Fist Warrior e $N2 Splinter Fist Taskmaster, poi torna da ⟦Sirra Von'Indi=Sirra Von'indi⟧ a ⟦Darkshire=Borgoscuro⟧ per saperne di più.", "Un arco lasciato dallo spirito di Merrick Valor, celebre guardiano che andava fiero di tenere le strade al sicuro dai nemici invasori.\n\nDato che lo spirito di Merrick vaga ancora per le strade, forse la sua questione in sospeso era scacciare gli invasori vicino alla sua casa a ⟦Raven Hill=Collecorvo⟧. Forse sono gli ogre a sud del paese a turbare il suo spirito.", nil, nil, 0xfe4f08e4, 0xea183417, 0xd5097423, nil, nil, "...mm" },
  [96139] = { "La famiglia Valor", "Cerca a ⟦Raven Hill=Collecorvo⟧ qualunque cosa di interesse e torna da ⟦Sirra Von'Indi=Sirra Von'indi⟧ a ⟦Darkshire=Borgoscuro⟧.", "In tempi bui come questi, è importante ricordare i nostri eroi quanto i nostri nemici. ⟦Darkshire=Borgoscuro⟧ non sarebbe ancora in piedi se non fosse per il coraggio di gente come la buona Lady Althea, o di chi perse la vita a ⟦Raven Hill=Collecorvo⟧.\n\nHai letto molto su ⟦Raven Hill=Collecorvo⟧? No, certo che no. La sua storia è stata cancellata insieme alla sua gente. La mia biblioteca, per quanto notevole, ha ben poco sull'argomento.\n\nSe per caso trovi qualcosa, apprezzerei se me lo portassi qui. Quella gente merita di essere ricordata.", "Hai trovato qualcosa? Non ci spero molto.", "Questo tomo sembra parlare della famiglia Valor. Credo di aver sentito parlare di alcuni di loro. Brava gente. Non so se meritino un intero libro tutto per loro.\n\nTi farò una copia del tomo. Se durante i tuoi viaggi trovi altro che li riguardi, sarà un piacere prenderlo in consegna.", 0x27a57039, 0x2c2db2c8, 0xb8e94707, 0xd0323cfc, 0xba858917, "....." },
  [96204] = { "L'ira della Windshaper", "Accompagna Lumina Windsinger e aiutala a fuggire da ⟦Fenris Keep=Forte Fenris⟧.", "Ora che sono libera, farò pentire queste vili creature di aver mai posato gli occhi su una Windshaper.\n\nAndiamocene di qui, {class}.", nil, "Grazie ancora, {name}. Ho fatto conoscenza con Trevan qui, che, a quanto ho saputo, ti ha mandato sulle mie tracce.\n\nFinora, nei miei viaggi, ho sentito dire cose... poco caritatevoli sui paladini. Da elfa shen'dorei toccata dal cielo che viaggia nei territori dell'Orda, capisco bene con quanta facilità l'intolleranza e il pregiudizio possano mettere radici.\n\nTu e quelli come te avete un'amica tra i Windshaper.", 0x537b0fef, 0xdc69980b, 0x0c4dedf9, nil, 0x893e3e79, "...m." },
  [96222] = { nil, "Porta il ⟦Maraudine Key Fragment=Frammento della Chiave di Maraudon⟧ a Umarak, a ⟦Desolace=Desolanda⟧.", "Mentre la guerra infuria in tutta la regione, i centauri ⟦Maraudine=Maraudon⟧ restano incontrastati nella ⟦Valley of Spears=Valle delle Lance⟧. Temo che col tempo diventino spietati e fomentino altri disordini, se gli altri clan continueranno a chiudere un occhio sulla loro presenza.\n\nKhan Hratha possiede un ⟦Maraudine Key Fragment=Frammento della Chiave di Maraudon⟧, e voglio averlo come arma di trattativa. Procurati il bocchino di un corno da guerra dai centauri del posto e usalo per sfidarlo in cima al picco più alto.\n\nPortami la chiave e avrò una proposta per te.", nil, nil, 0xa9d55f09, 0xffb7769a, 0x95b5e8c9, nil, nil, "e..mm" },
  [96241] = { "Parliamo di tossine, mon", "Usa il Toxin Extractor per raccogliere $N1 Gloomrise Toxin Sample dai Gnawed Corpse di Gloomrise.", "Succede qualcosa di strano laggiù a Gloomrise. Il vecchio Mazu'kon sente parlare un sacco di queste brutte bestiacce nuove che zampettano dappertutto là intorno.\n\nC'è chi dice che quegli insetti schifosi hanno un veleno con proprietà uniche, e questo mi fa venire curiosità. Prendi il mio estrattore. Usalo sui cadaveri sparsi per quel posto per raccogliere il veleno. Fallo, e io sarò in debito con te, mon.", nil, nil, 0xb964176e, 0x8fd016de, 0x40a8707c, nil, nil, "...mm" },
  [96243] = { "Il richiamo della terra", "Trova Teo Hammerstorm a Dun Morogh.", "È ora che tu dia ascolto alla terra, <valoroso/valorosa> <Sciamano/Sciamana>. Gli elementi già ti pizzicano la pelle, ma una volta che avrai parlato con la pietra, il suolo stesso si farà saldo sotto i tuoi piedi... e nella tua anima.\n\nCerca Teo Hammerstorm nella ⟦Coldridge Valley=Valle Crestafredda⟧. Lo troverai dentro ⟦Anvilmar=Forgiamara⟧, una roccaforte forgiata con martello, fuoco e volontà.", nil, nil, 0xe316c17f, 0xf8e81384, 0x13c0eb8d, nil, nil, "...mm" },
  [96259] = { "In difesa dei morti", "Uccidi $N1 Gloomrise Hatchling e $N2 Gloomrise Soldier.", "C'è un antico luogo di sepoltura tauren nel posto chiamato Gloomrise, appena a nord-ovest di questo accampamento. Di recente è stato infestato da una covata di ragni particolarmente feroci. Questi ragni non sono solo una minaccia per la gente di Mulgore: stanno anche danneggiando un luogo che la maggior parte dei tauren considera sacro.\n\nMi faresti un grande servizio se andassi a Gloomrise e mettessi fine a questa infestazione. Gli antenati ti sorrideranno di certo, se ci riuscirai.", nil, nil, 0x554fb829, 0xfedbb124, 0x55e7bece, nil, nil, "...mm" },
  [96260] = { "Più forte dell'acciaio", "Raccogli $N1 Crystalline Silk dai Gloomrise Spinner.", "Hai sentito cos'è successo al luogo di sepoltura di Gloomrise? Ragni giganti, che si dice abbiano un veleno così potente da risvegliare i morti, si sono diffusi come un incendio. Brutta faccenda, se vuoi il mio parere.\n\nUno degli esploratori mandati a indagare è tornato mezzo morto e coperto da una seta di ragno cristallina incredibilmente resistente. Ne ho raccolta quanta ho potuto, ma mi servirebbero davvero altri campioni di questa seta per studiarla ancora.\n\nPortami altra seta cristallina e ti ricompenserò.", nil, nil, 0x9eb7d49a, 0x87e2b5d5, 0x7ddec3da, nil, nil, "...mm" },
  [96261] = { "La madre della covata", "Uccidi Broodmother Valraxx a Gloomrise.", "Come accade spesso con infestazioni come quella che affrontiamo a Gloomrise, è una sola potente matriarca a causare la rapida diffusione di una popolazione ostile di ragni.\n\nSe vogliamo scacciare queste bestie per sempre, dovremo trovare la capostipite e farla finita con lei. Quando andrai a Gloomrise, cerca la madre della covata e distruggila. Ti consiglio di portare degli alleati e di essere <pronto/pronta> a tutto. Questi non sembrano ragni comuni.", nil, nil, 0xcdf04d8e, 0x37e65943, 0x0eed8922, nil, nil, "...mm" },
  [96264] = { "Aiuto elementale", "Sconfiggi ⟦Charlga Razorflank=Charlga Fiancospino⟧ nelle ⟦Razorfen Kraul=Gallerie di Lamaspina⟧ e raccogli informazioni sui piani dei verrospini.", "Dunque adesso sei <uno/una> <sciamano/sciamana> pezzo grosso, eh? Hai padroneggiato gli elementi e vuoi metterli a buon uso? Credo di avere proprio quel che fa per te.\n\nSe vuoi il rispetto degli elementi, devi ripagare i tuoi debiti con loro. Loro aiutano te, tu aiuti loro. E proprio ora hanno bisogno di tutto l'aiuto possibile contro chi vorrebbe abusare del loro potere.\n\nLa terra brontola, {name}. Parla di verrospini che si radunano per un rituale di terribile potere. Dobbiamo andare a indagare nelle loro gallerie e scoprire cosa stanno combinando. Riportami qualunque cosa trovi.", nil, nil, 0x3a904965, 0xd3648ee8, 0x7dfb9fdc, nil, nil, "...mm" },
  [96294] = { "Una verità più oscura", "Porta la lettera che hai recuperato da Broodmother Valraxx a Muln Earthfury, allo Skywatcher Plateau.", "<La madre della covata che hai appena ucciso non è affatto un ragno, ma un druido elfo della notte che aveva assunto una distorta forma animale. Mille domande ti affollano la mente sulla natura, e sullo scopo, dei ragni di Gloomrise.\n\nNoti un biglietto che spunta dalle pieghe della veste dell'elfo morto. Forse questo documento potrà rispondere ad alcune delle domande che ti riempiono la testa.>", nil, nil, 0xceb16734, 0xff9e4493, 0x8d307e49, nil, nil, "...mm" },
  [96339] = { "Ricompensa dell'eredità: Replica Ironforge Air Rifle", nil, nil, nil, nil, 0x049ac689, nil, nil, nil, nil, ".mmmm" },
  [96383] = { "Ricompensa dell'eredità: Spectral Bear Cub", nil, nil, nil, nil, 0x282c1e94, nil, nil, nil, nil, ".mmmm" },
  [96390] = { "Stroncarli sul nascere", "Uccidi $N1 Dark Iron Spy a Dun Morogh.", "Delle spie ⟦Dark Iron=Ferroscuro⟧ si sono infiltrate a Dun Morogh. A che scopo non posso dirlo con certezza, ma è un problema che dobbiamo stroncare sul nascere, prima che cresca.\n\nDirigiti a est, verso il ⟦Ironband's Compound=Presidio di Ferrocollo⟧, e uccidi le spie ⟦Dark Iron=Ferroscuro⟧ che trovi lì.", nil, "Questi Ferroscuro saranno anche nostri cugini, ma non sono famiglia, questo è certo. Non verso lacrime per le disgrazie che capitano a quelli che si allontanano troppo da quella loro montagna maledetta.\n\nSperiamo che basti a dissuaderli da altre incursioni in queste terre.", 0x5f38218b, 0x10fb22fa, 0x9db0e0ef, nil, 0xd5731f3e, "...m." },
  [96391] = { "Una mappa dei sotterranei", "Consegna la Dark Iron Map al veggente della terra Farsen, a Dun Morogh.", "La mappa che hai in mano sembra mostrare una complessa rete di gallerie e strade sotterranee che convergono tutte in un punto proprio sotto ⟦Ironforge=Forgiardente⟧.\n\nNon puoi sapere con certezza cosa dicano le rune, scritte nella brutta e spigolosa lingua runica dei nani ⟦Dark Iron=Ferroscuro⟧, ma puoi intuire lo scopo di queste gallerie. Mentre leggi la mappa, una folata di vento ti investe e senti, debole, una voce nanica portata dal vento. Il veggente della terra Farsen deve vederla.", "Oh, e questo cos'è?", "A giudicare da questa mappa, sembra proprio che questi Ferroscuro stiano preparando una specie di incursione nelle cripte sotto ⟦Ironforge=Forgiardente⟧. La banda che hai sgominato a est dev'essere una forza di ricognizione.\n\nGrazie per avermela portata. Se ci sbrighiamo, forse riusciremo a precederli, qualunque sia il loro obiettivo laggiù.", 0x9d9cce92, 0x0559f95b, 0x9898e535, 0x52844eeb, 0x1c2fe859, "....." },
  [96392] = { "Lo sguardo di Farsen", "Parla con il veggente della terra Farsen e chiedigli di prestarti la sua vista lontana per osservare la minaccia ⟦Dark Iron=Ferroscuro⟧.", "Salute a te, amico. Mi chiamo Farsen, veggente della terra, e sono a Dun Morogh in visita dal ⟦Aerie Peak=Picco dell'Aquila⟧. Mentre viaggiavo, non ho potuto fare a meno di notare che abbiamo, be'... un certo problema di nani Ferroscuro.\n\nSe hai un momento, posso mostrarti cosa intendo. Ho un pizzico di magia che dovrebbe fare al caso nostro.", nil, "Allora, ora capisci, {class}? Sono fitti come scarafaggi, e sono solo quelli che vediamo dal cielo.\n\nMi sembri abbastanza robust<o/a>. Che ne dici di un po' di violenza?", 0x9243cd15, 0x987a4089, 0xce20450c, nil, 0xf760c717, "...m." },
  [96393] = { "Incursione nella Vecchia ⟦Ironforge=Forgiardente⟧", "Entra nella Hall of Thanes sotto la Vecchia ⟦Ironforge=Forgiardente⟧ e prendi la testa di Durgen Dirgehammer.", "Raduna qualche alleato e scendi nelle caverne sotto la Vecchia ⟦Ironforge=Forgiardente⟧. Entra nella Hall of Thanes e spingiti fino alle cripte inferiori.\n\nIl mio ⟦Dark Iron=Ferroscuro⟧ è un po' arrugginito, ma riesco a decifrare un nome: un certo Durgen Dirgehammer. Probabilmente è lui il comandante. Prendi la sua testa e consegnala a re Magni Bronzebeard.\n\nAh, e quando lo fai, digli che il suo vecchio amico Farsen gli manda i suoi saluti!", "Di che cosa hai bisogno, <cittadino/cittadina>?", "Un'incursione ⟦Dark Iron=Ferroscuro⟧... proprio sotto i nostri piedi? Be', è un sollievo sapere che il comandante ⟦Dark Iron=Ferroscuro⟧ è stato eliminato.\n\nLe guardie entreranno a ripulire il resto della marmaglia. Faremo in modo che le brecce vengano sigillate e i livelli inferiori rinforzati, così che nessun'altra incursione sia possibile.\n\nGrazie per il tuo servizio a ⟦Ironforge=Forgiardente⟧, {class}. Accetta questo piccolo pegno della mia gratitudine. Ah, e se rivedi quel vecchio abbracciarocce Granmartello di Farsen, digli di venirmi a trovare come si deve.", 0x48866402, 0xe0bec594, 0xa08604c5, 0xa75dc075, 0x1c39cb14, "....." },
  [96394] = { "I morti senza pace", "Uccidi $N1 Enraged Apparition e $N2 Tormented Soul, e dai riposo allo spirito del thane ⟦Anvilmar=Forgiamara⟧.", "Qualcosa ha disturbato le tombe giù nella Hall of Thanes, e dal profondo delle cripte si sentono strani rumori. Gli spiriti dei morti hanno il sonno leggero, e qualunque cosa stia succedendo laggiù sembra averli spaventati.\n\nScendi laggiù e vedi cosa puoi fare per noi. Se qualche morto si è svegliato... be', rimettilo a dormire!", nil, "Ah, bene, allora è fatta. Non posso permettere che gli altri custodi si rifiutino di entrare nella sala a fare il loro dovere per colpa di «fantasmi» e «morti arrabbiati», no?", 0x69066003, 0x6a43847e, 0xd9e1bd9c, nil, 0xd8017bd3, "...m." },
  [96395] = { "Un antico rancore", "Dai riposo allo spirito di Faldrim ⟦Anvilmar=Forgiamara⟧, poi torna dal Ghostly Attendant nella Hall of Thanes.", "Il... thane... il mio potente... thane... ha... bisogno di... riposare.\n\nTi prego... aiutalo... aiutalo... a riposare...\n\nConsumato... da un... antico... rancore... Nessun... riposo...", "<La figura spettrale fissa il vuoto oltre di te. La sua bocca si muove, ma si sentono solo bassi rantoli indistinti.>", "Il mio... thane... riposa... sì... riposa.\n\nGrazie... a te...\n\nIo... riposo...", 0x372fadb2, 0xf47ad935, 0x22f3d060, 0x36b0ce0b, 0x80ede96a, "....." },
  [96403] = { "Cimeli importanti", "Raccogli $N1 Dwarven Heirloom nella Hall of Thanes.", "Ehi, tu, <avventuriero/avventuriera>... mi servirebbe proprio il tuo aiuto.\n\nStavo sgattaiolando... ehm... «pattugliando» le cripte, quando una squadra di nani ⟦Dark Iron=Ferroscuro⟧ è sbucata dalle profondità a bordo di talpe meccaniche! Non so cosa siano venuti a fare, ma laggiù c'è un bottino inestimabile... ehm, o meglio... voglio dire, ci sono «importanti cimeli culturali»! Ti prego, recupera tutti i reperti di questo tipo che vedi e riportali qui.\n\nTi assicuro che tutto ciò che recupererai sarà catalogato e restituito al suo legittimo posto d'onore.", "<Thom si sfrega distrattamente le mani mentre ti guarda.>", "Ma guardati, coraggios<o/a> quanto intraprendente! Sono uno gnomo di parola, e la tua ricompensa è ben meritata!\n\nOra fammi dare un'occhiata al bottino... ehm, voglio dire... ai cimeli recuperati. Devo cominciare a valutarli... pardon, a «catalogarli», così da poterli rimettere al loro posto il prima possibile.", 0xdb5e0561, 0x7bf6ecf5, 0x1019355e, 0xb065081e, 0xd63d4304, "....." },
  [96408] = { "Un visitatore a Dun Morogh", "Ispeziona l'accampamento che domina la ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧.", "Ieri notte uno dei nostri montanari ha avvistato un fuoco da campo su un pendio a est. Sembra piuttosto in alto, sopra la ⟦Gol'Bolar Quarry=Cava di Gol'Bolar⟧.\n\nProbabilmente non è niente, ma vorrei che andassi a dare un'occhiata a quell'accampamento. Se sono amici, nessun danno. Se non lo sono... be', sai cosa fare.", nil, "Salute, amico. Come va?", 0x7b3a9976, 0x89d2ded4, 0x1a6a0853, nil, 0x9c8725d7, "...m." },
  [96604] = { "La vita all'aria aperta", "Siediti vicino al Brakk's Basic Campfire e attendi di ricevere il beneficio Boosted Rest.", "Lok-tar, {class}. Hai proprio l'aria dell'avventuriero, e questo è un bene. Il mondo ha bisogno di altre anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nIn questo mestiere, per avere successo, dovrai imparare a cavartela nelle terre selvagge. Non so quanto tu sia <bravo/brava> all'aperto, ma qualcosa probabilmente posso insegnartelo, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego io come si fa.", nil, "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0xc9a7eaed, 0x1dfc83c1, nil, 0x2eacf33d, "...m." },
  [96605] = { "La vita all'aria aperta", "Siediti vicino al Kaga's Basic Campfire e attendi di ricevere il beneficio Boosted Rest.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", nil, "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0x6d44875e, 0xb221e6cb, nil, 0x2eacf33d, "...m." },
  [96606] = { "La vita all'aria aperta", "Siediti vicino al Lyreena's Basic Campfire e attendi di ricevere il beneficio Boosted Rest.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", "Possedere le abilità necessarie per sopravvivere all'aperto è fondamentale. Un avventuriero ben riposato e ben preparato ha molte più probabilità di sopravvivere a questo stile di vita.", "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0xbbb8647e, 0xb221e6cb, 0x452722a2, 0x2eacf33d, "....." },
  [96607] = { "La vita all'aria aperta", "Siediti vicino all'Eleanor's Basic Campfire e attendi di ricevere il beneficio Boosted Rest.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", nil, "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0x71b45cb3, 0xb221e6cb, nil, 0x2eacf33d, "...m." },
  [96608] = { "La vita all'aria aperta", "Siediti vicino all'Eric's Basic Campfire e attendi di ricevere il beneficio Boosted Rest.", "Salute, {class}. Si vede che hai l'aria dell'avventuriero. Questo è un bene. Il mondo ha bisogno di più anime irrequiete come noi, in cerca di fortuna e di gloria.\n\nPer avere successo in questo mestiere dovrai imparare a prosperare nelle terre selvagge. Non so quanto tu sia pratic<o/a> di vita all'aperto, ma probabilmente posso insegnarti un paio di cose, se hai voglia di imparare.\n\nSiediti vicino al fuoco e mettiti comod<o/a>. Ti spiego tutto io.", nil, "Ora che abbiamo imparato le basi, perché non vai a imparare un mestiere dagli istruttori del villaggio qui vicino? Ti insegneranno anche a costruire un'attrezzatura da accampamento adatta alla tua nuova professione.", 0x561c5fa2, 0x2837fcc0, 0xb221e6cb, nil, 0x2eacf33d, "...m." },
  [96626] = { "Campeggio 101: Cucina", "Parla con Tomas a ⟦Goldshire=Borgodoro⟧ per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0x48b91f09, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96627] = { "Vita da avventuriero", "Parla con Sam Sarsparilla nei pressi di ⟦Goldshire=Borgodoro⟧.", "{name}, finora hai dimostrato il tuo valore come protett<ore/rice>. Per questo ora ti affido un compito insolito.\n\nHo sentito parlare di un nuovo avventuriero lungo la strada, vicino a ⟦Goldshire=Borgodoro⟧. Va' a vedere che cosa sta facendo.", nil, "Grazie per esserti preoccupat<o/a> per me, {class}. Quel maresciallo si agita per niente.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0x24f0776f, 0x24463491, nil, 0xeb1c22f1, "...m." },
  [96628] = { "Vita da avventuriero", "Consegna il Supply Bundle a Eric Brighthammer nei pressi di Kharanos.", "Aspetta, {name}. Ho un'altra richiesta da farti, prima che tu affronti quella galleria.\n\nI miei montanari hanno segnalato un avventuriero comparso appena fuori Kharanos. Potresti consegnargli queste provviste?", "Sei qui per imparare ad accamparti nelle terre selvagge?", "Dici che vengono dai montanari? Sì, mi fanno comodo. Grazie, {class}.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0xbfabdfa9, 0x1f02236b, 0xf7a7f9bd, 0x5f83030c, "....." },
  [96629] = { "Campeggio 101: Cucina", "Parla con Gremlock Pilsnor a Kharanos per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0xfb18b446, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96630] = { "Vita da avventuriero", "Porta il diario a Lyreena Duskblade nei pressi di Dolanaar.", "<Il diario sembra piuttosto ordinario: racconta la vita e le avventure di qualcuno di cui non hai mai sentito parlare.\n\nDiverse pagine parlano di campeggio. Sembra proprio... divertente.>", "Sei qui per imparare ad accamparti nelle terre selvagge?", "È il mio diario? Era da un po' che non lo trovavo più. Grazie, {class}.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0xc5322669, 0xfeee01ed, 0xf7a7f9bd, 0xd8b07e29, "....." },
  [96634] = { "Campeggio 101: Cucina", "Parla con Zarrin a Dolanaar per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0xa03560df, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96638] = { "Vita da avventuriero", "Parla con Raan Wildwind nei pressi di Shen'dar Village.", "Sempre più avventurieri come te cercano gloria e fortuna lontano dalla sicurezza di Thendal Grove. Uno di loro si è accampato fuori da Shen'dar Village, lungo la strada che da Thendal Grove porta a sud-ovest.\n\nCercalo e scopri che cosa puoi imparare da lui che ti sia utile nei tuoi viaggi.", nil, "Ben trovat<o/a>!", 0x1afc3318, 0x72c75d4e, 0x5990b6bd, nil, 0x47da9bb0, "...m." },
  [96646] = { "Campeggio 101: Cucina", "Parla con Zerril Softbreeze a Shen'dar Village per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", "Un buon fuoco da campo è la base di ogni buon accampamento.", "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0x8b592b5f, 0x611be1a4, 0x20282ef3, 0x4d6e308e, "....." },
  [96652] = { "Vita da avventuriero", "Porta il diario a Brakk nei pressi di ⟦Razor Hill=Tranciacolle⟧.", "<Il diario sembra piuttosto ordinario: racconta la vita e le avventure di qualcuno di cui non hai mai sentito parlare.\n\nDiverse pagine parlano di campeggio. Sembra proprio... divertente.>", "Sei qui per imparare ad accamparti nelle terre selvagge?", "È il mio diario? Era da un po' che non lo trovavo più. Grazie, {class}.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0x19108351, 0xfeee01ed, 0xf7a7f9bd, 0xd8b07e29, "....." },
  [96655] = { "Campeggio 101: Cucina", "Parla con il cuoco Torka a ⟦Razor Hill=Tranciacolle⟧ per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", nil, "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0x4f2cbefa, 0x611be1a4, nil, 0x4d6e308e, "...m." },
  [96656] = { "Vita da avventuriero", "Parla con Eleanor Shackleton nei pressi di Brill.", "{name}, finora ti sei <dimostrato/dimostrata> degn<o/a> di fiducia nelle tue imprese contro la ⟦Scarlet Crusade=Crociata Scarlatta⟧. Per questo ora ti affido un compito insolito.\n\nHo sentito parlare di una nuova avventuriera lungo la strada, vicino a Brill. Va' a vedere che cosa sta facendo.", nil, "Non ho niente a che fare con la ⟦Scarlet Crusade=Crociata Scarlatta⟧, se non si fosse capito. Sono solo un'avventuriera di passaggio, prima della mia prossima spedizione nelle terre selvagge.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0x60140125, 0x7846cd95, nil, 0xbb601ab5, "...m." },
  [96658] = { "Campeggio 101: Cucina", "Parla con William Pickman a Brill per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", nil, "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0xca2cf982, 0x611be1a4, nil, 0x4d6e308e, "...m." },
  [96659] = { "Vita da avventuriero", "Consegna il Supply Bundle a Kaga Wildhoof nei pressi del ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Aspetta, {name}. Ho un'altra richiesta da farti, prima che tu ci lasci.\n\nC'è un'avventuriera di nome Kaga Wildhoof che si è accampata appena fuori dal ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. In passato mi ha aiutato molto, e ora vedo l'occasione di ricambiarla. Potresti consegnarle queste provviste?", "Sei qui per imparare ad accamparti nelle terre selvagge?", "Ti manda il capo Hawkwind? Gliel'avevo detto, allora, che non volevo nessun compenso, ma a quanto pare non mi ha ascoltata. Grazie, {class}.\n\nEhi, anche tu hai l'aria dell'avventuriero. Ti andrebbe di imparare ad accamparti?", 0x1afc3318, 0x8ee06ce3, 0xc65676fe, 0xf7a7f9bd, 0x113825f8, "....." },
  [96661] = { "Campeggio 101: Cucina", "Parla con ⟦Pyall Silentstride=Pyall Passo Silente⟧ al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ per imparare a cucinare.", "Così vuoi saperne di più sull'arte di accamparsi, eh? Ottima idea, {class}. Il primo passo per ogni avventuriero è imparare a cucinare e ad accendere un fuoco da campo.\n\nCucinare non serve solo a preparare piatti gustosi: è anche la base del tuo accampamento.", nil, "Con questo potrai allestire un accampamento ovunque nelle terre selvagge. Quello che hai imparato sono solo le basi, quindi non potrai sistemarci intorno troppi arredi.\n\nMigliora la tua abilità in Cucina e forse potrai imparare ad accendere fuochi ancora più grandi.\n\nPuoi anche imparare le basi dell'arredamento dei tuoi accampamenti dagli istruttori di altre professioni, se te la cavi nelle loro arti.", 0x61f383d0, 0xbe1a3274, 0x611be1a4, nil, 0x4d6e308e, "...m." },
  [96735] = { nil, nil, nil, nil, nil, 0x0f38dabc, nil, nil, nil, nil, "emmmm" },
  [96774] = { nil, "Recupera un Ancient Gurubashi Idol dalla Drowned City.", "Gli antichi Gurubashi di Rovotorto erano maestri di oscura magia del sangue. Si dice che usassero idoli di verargento puro per incanalare quel voodoo cattivo cattivo.\n\nIl vecchio Mazu'kon darebbe qualsiasi cosa per mettere le mani su uno di quegli idoli... per studio, capisci. Che ne dici di radunare qualche amico e fare un bel colpo in quella città sommersa che spunta dal mare al largo della costa di Rovotorto? Uccidi il sacerdote dall'aria più importante che trovi là dentro, e di sicuro avrà quello che cerco.", nil, nil, 0x5f76897d, 0x4a847e99, 0xf74ccc84, nil, nil, "e..mm" },
  [96779] = { "Sabotaggio alla ⟦Syndicate=Lega dei Tagliagole⟧", "Trova Lord Tomas nel ⟦Durnholde Keep=Forte Durnholde⟧, sulle ⟦Hillsbrad Foothills=Alture di Colletorto⟧, e uccidilo. Poi torna da ⟦Myrokos Silentform=Myrokos Silente⟧.", "A volte, {race}, basta un solo taglio nel punto giusto per stendere un nemico. Spesso vale lo stesso per le organizzazioni.\n\nI nostri agenti hanno individuato un bersaglio chiave tra le file della ⟦Syndicate=Lega dei Tagliagole⟧: un uomo di nome lord Tomas.\n\nHa un ruolo fondamentale nel funzionamento del ⟦Durnholde Keep=Forte Durnholde⟧, sulle ⟦Hillsbrad Foothills=Alture di Colletorto⟧. Se vuoi servire ⟦Ravenholdt=Corvolesto⟧, va' a Durnholde ed eliminalo. Più in fretta e in silenzio, meglio è.", nil, nil, 0x12459469, 0xd843986f, 0xd52e350a, nil, nil, "...mm" },
  [96781] = { "Che cosa avranno in mente?", "Ruba con destrezza il Barton's Scouting Report dalle tasche di Barton. Poi porta il rapporto a ⟦Myrokos Silentform=Myrokos Silente⟧ al ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧.", "Abbiamo notato una squadra di esploratori della ⟦Syndicate=Lega dei Tagliagole⟧ che si aggira tra le rovine di Alterac, guidata da un uomo di nome Barton.\n\nÈ chiaro che stanno cercando qualcosa, ma non posso sapere cosa senza leggere i suoi rapporti di ricognizione.\n\nTi chiedo di sfilargli il rapporto dalle tasche, invece di ucciderlo. La morte di Barton farebbe capire alla ⟦Syndicate=Lega dei Tagliagole⟧ che li teniamo d'occhio, e di certo prenderebbero contromisure per coprire le loro tracce.\n\nSe vuoi trovarlo, molto probabilmente è con quelli della ⟦Syndicate=Lega dei Tagliagole⟧ a Strahnbrad.", nil, nil, 0xe4f9042e, 0x63217e37, 0x8e8d9103, nil, nil, "...mm" },
  [96782] = { "Recupero segreto", "Trova la Blade of House Perenolde e la Royal Aegis of Perenolde tra le rovine di Alterac. Poi portale a ⟦Myrokos Silentform=Myrokos Silente⟧.", "Pare che il nostro amico Barton ci abbia reso le cose molto facili. Cerca due cimeli della famiglia Perenolde tra le rovine di Alterac: la Blade of House Perenolde, una spada, e la Royal Aegis of Perenolde, uno scudo.\n\nDal rapporto, sembra che queste armi si trovino in due torri tra le rovine. Meglio prenderle prima della ⟦Syndicate=Lega dei Tagliagole⟧.\n\nGli ogre che occupano le rovine sono feroci, ma confido che saprai passare loro accanto senza dover sporcare di sangue la tua lama.", nil, nil, 0x38463dcf, 0x0dd136cc, 0xbaff77cb, nil, nil, "...mm" },
  [96783] = { "Una via d'accesso", "Ruba un'uniforme della ⟦Syndicate=Lega dei Tagliagole⟧ al ⟦Northfold Manor=Maniero dei Norten⟧ per infiltrarti nel ⟦Stromgarde Keep=Forte di Stromgarde⟧.", "Il ⟦Stromgarde Keep=Forte di Stromgarde⟧ è una delle roccaforti più grandi della ⟦Syndicate=Lega dei Tagliagole⟧. Molti degli affari più importanti dell'organizzazione si concludono dietro le sue mura.\n\nMi è giunta voce di un certo scambio tra membri della ⟦Syndicate=Lega dei Tagliagole⟧, da qualche parte negli ⟦Arathi Highlands=Altopiani d'Arathi⟧, e sono certo che i dettagli di questo scambio si trovino da qualche parte a Stromgarde.\n\nPer infiltrarti nel forte senza destare sospetti ti servirà un travestimento. Vedi se riesci a trovarne uno tra quelli della ⟦Syndicate=Lega dei Tagliagole⟧ fuori dal forte, al ⟦Northfold Manor=Maniero dei Norten⟧.", nil, nil, 0x1b0f8afe, 0xaa986c18, 0x7b8b0be2, nil, nil, "...mm" },
  [96784] = { "Maestro del travestimento", "Con il travestimento da membro della ⟦Syndicate=Lega dei Tagliagole⟧, trova qualcuno nel ⟦Stromgarde Keep=Forte di Stromgarde⟧ che sappia dell'accordo segreto.", "<Ricordi le istruzioni di Myrokos: scoprire qualcosa su un affare importante della ⟦Syndicate=Lega dei Tagliagole⟧ nel ⟦Stromgarde Keep=Forte di Stromgarde⟧. Con il tuo travestimento dovresti poter parlare con i membri della ⟦Syndicate=Lega dei Tagliagole⟧ con una certa libertà. Di sicuro qualcuno di loro sa qualcosa.>", nil, nil, 0x87afd4b0, 0x839d37e0, 0xac13dcec, nil, nil, "...mm" },
  [96785] = { "Bocca cucita", "Trova qualcosa nel ⟦Stromgarde Keep=Forte di Stromgarde⟧ che convinca Anastasia a rivelare i dettagli dell'accordo segreto.", "Chi ti credi di essere? Arrivi qui e ficchi il naso negli affari ufficiali.\n\nNon racconto niente a <un/una> pivell<o/a> sugli affari dei pezzi grossi senza un buon motivo. A meno che tu non abbia qualcosa di importante, o di prezioso, per me, non ho niente da dirti.", nil, nil, 0x21897a89, 0xe27114b7, 0xce26588b, nil, nil, "...mm" },
  [96786] = { "Trappola per la ⟦Syndicate=Lega dei Tagliagole⟧", "Manda all'aria l'accordo segreto e prendi l'oggetto destinato alla ⟦Syndicate=Lega dei Tagliagole⟧. Poi torna da ⟦Myrokos Silentform=Myrokos Silente⟧ al ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧.", "Falconcrest ha mandato alcuni dei suoi a fare uno scambio nella parte meridionale del Muro di Thoradin. Non so cosa debbano ritirare. Dev'essere roba buona, perché tutti quelli coinvolti l'hanno tenuta segretissima. Credo che nemmeno quelli che la ritirano sappiano cos'è.\n\nÈ tutto quello che so. Non farmi pentire di avertelo detto.", nil, nil, 0x54ce55fd, 0x3c52e102, 0x27700057, nil, nil, "...mm" },
  [96800] = { "Restituzione in ritardo", "Recupera il libro The Lost Magic of the Runemasters dal ⟦Scarlet Monastery=Monastero Scarlatto⟧.", "Ehi, tu, {class}. Ho una faccenda per cui mi farebbe comodo un aiuto.\n\nGuarda caso sto scrivendo una tesi sugli antichi maestri delle rune Granmartello di Grim Batol, e mi serve un tomo in particolare per completare le mie ricerche. Secondo i nostri registri, un mago di nome Doan ha preso in prestito il libro dalla vecchia biblioteca di Dalaran prima della Terza Guerra e non l'ha mai restituito!\n\nL'arcanista Doan ora è rintanato nel ⟦Scarlet Monastery=Monastero Scarlatto⟧, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧. Recuperami quel libro e sarai ricompensat<o/a> a dovere.", nil, nil, 0xc02ef2a8, 0x6080a32a, 0x72b14b39, nil, nil, "...mm" },
  [96821] = { "Gambe in spalla", "Uccidi 6 Ridgeshade Creeper e 6 Ridgeshade Lurker nel sud di Durotar, poi fai rapporto a Gar'thok a ⟦Razor Hill=Tranciacolle⟧.", "Vediamo sempre meno viaggiatori da ⟦Razor Hill=Tranciacolle⟧, di questi tempi. Gli scorpidi non sono mai stati un granché, ma ora sento dire che ci sono ragni che fanno il nido lungo la strada.\n\nSe i tuoi viaggi ti portano a nord, uccidi qualche ragno lungo il cammino. Poi fai sapere a ⟦Razor Hill=Tranciacolle⟧ che la strada è un po' più sicura.", nil, "Da un po' di tempo i peoni hanno paura di viaggiare verso sud, {name}. Ora che hai ripulito un po' la strada, possiamo rimetterli al lavoro.", 0xb84a70d7, 0x3a400289, 0x05f6951d, nil, 0xd8c3f0b4, "...m." },
  [96822] = { "Per l'onore", "Raccogli il Raider's Battleaxe, il Raider's Bow e lo ⟦Raider's Shield=Scudo dell'Incursore⟧ nei dintorni del ⟦Tiragarde Keep=Forte di Tiragarde⟧, poi riportali a Turroc a ⟦Razor Hill=Tranciacolle⟧.", "Abbiamo perso molti valorosi guerrieri dell'⟦Horde=Orda⟧ quando abbiamo saccheggiato il ⟦Tiragarde Keep=Forte di Tiragarde⟧. Ora che gli umani hanno rinforzato le rovine, non possiamo recuperare le loro spoglie per onorarne degnamente la morte.\n\nVa' tra le rovine intorno al forte e cerca le armi lasciate dai nostri fratelli caduti. Le esporremo in un luogo d'onore.", "Hai fatto ciò che ti ho chiesto?", "Questi guerrieri saranno sempre ricordati, {name}. Te ne sei assicurat<o/a> tu.", 0x312a6de6, 0x12f27d5e, 0x59e8004e, 0x914533e6, 0xfc5f93be, "....." },
  [96825] = { "Un frutto che morde", "Il cuoco Torka di ⟦Razor Hill=Tranciacolle⟧ vuole che tu raccolga 8 Prickly Pear Fruit nelle ⟦Razormane Grounds=Terre dei Chiomaguzza⟧, a ovest del villaggio.", "I nostri cacciatori e pescatori portano tanto cibo saporito per le truppe, ma è raro che portino qualcosa di dolce.\n\nHo visto un cactus che produce un frutto spinoso e gustoso. Ma cresce solo sulle colline a ovest, dove quei miserabili verrospini hanno i loro accampamenti. Supera i verrospini e portami un po' di quei frutti. E fa' attenzione: i frutti sono spinosi quanto i verrospini!", "Hai trovato i frutti?", "Li userò per preparare qualcosa di gustoso, e terrò da parte i semi per piantarli. Un giorno avremo fichi d'India in tutta Orgrimmar!", 0x5d0fb368, 0x56b9c042, 0x2c431c3a, 0xa390104c, 0x879b29b5, "....." },
  [96873] = { "Un peso al collo", "Pa'zula, al ⟦Sen'jin Village=Villaggio di Sen'jin⟧, vuole che tu raccolga 3 Luminous Residue. Il Luminous Residue si ottiene disincantando gli Hexed Pendant lasciati dai troll delle ⟦Echo Isles=Isole dell'Eco⟧.", "I troll a est di qui hanno perso la volontà per colpa del santone Zalazane. Usa molte magie crudeli per tenere in pugno la mente dei suoi prigionieri, ma uno dei suoi trucchi preferiti è fargli indossare pendenti avvolti da malvagi incantesimi di vincolo.\n\nEsercita le tue abilità di incantamento spogliando questi pendenti della loro magia, e portami i risultati. E non metterne uno al collo per sbaglio, se ci tieni alla tua libertà!", "Che cos'hai per me, {name}?", "Ottimo lavoro. Peccato per i troll uccisi, ma ora che gli incantesimi di vincolo sono stati rimossi, i loro spiriti possono riposare.", 0xdbeec7f9, 0x2e3399cb, 0x4f2abab1, 0x777ed8a4, 0xd6297264, "....." },
  [96874] = { "L'ascia spinosa", "Ug'thok, a Orgrimmar, vuole che tu raccolga 5 Weathered Spine dalle bestie della ⟦Thunder Ridge=Fossa del Tuono⟧, insieme a 5 Pietra da Molatura Grezza.", "Hai visto le enormi bestie della ⟦Thunder Ridge=Fossa del Tuono⟧? Continuo a pensare che gli aculei sulla loro schiena sarebbero perfetti per forgiare la testa di una possente ascia. Saru si è messo a ridere quando gliel'ho detto... ma che ne sa lui!?\n\nCome parte delle tue lezioni di forgiatura, puoi darmi una mano! Portami un po' di quegli aculei, insieme a delle pietre da molatura per affilarli.", nil, nil, 0xf6bb3113, 0xf3ac90a4, 0xc9a1f75b, nil, nil, "...mm" },
  [96875] = { "Le bestie della ⟦Thunder Ridge=Fossa del Tuono⟧", "Kamari, a Orgrimmar, vuole che tu raccolga 5 Rough Lizard Hide dalle bestie della ⟦Thunder Ridge=Fossa del Tuono⟧, insieme a 2 Pelle Leggera Trattata.", "Orgrimmar non smette mai di crescere, {class}. E quando i peoni hanno bisogno di pelli per rivestire le pareti e i tetti dei nostri nuovi edifici, vengono da me!\n\nLe pelli delle lucertole della ⟦Thunder Ridge=Fossa del Tuono⟧ di solito sono troppo spesse per farne armature, ma sono un ottimo materiale da costruzione. Portami un po' delle loro pelli, insieme a qualche pelle leggera trattata. Vediamo come te la cavi con il cuoio!", nil, nil, 0x6150b99e, 0x6f6f97d3, 0x8796ce18, nil, nil, "...mm" },
  [96876] = { "Lo zaino perduto di Ukor", "Riporta lo zaino a Ukor, nel sud di Durotar.", "Sulla patta dello zaino è cucito alla buona il nome \"Ukor\".", nil, nil, 0xae92df38, 0x533f75f6, 0x6bd7c611, nil, nil, "...mm" },
  [96877] = { "Lo zoccolo di Halikor", "Consegna lo Halikor's Hoof a Orgrimmar.", "L'enorme zoccolo è la prova della tua vittoria sulla possente lucertola.", "Sì?", "Che trofeo, {class}! Dev'essere stato un bel combattimento!", 0x795887e1, 0xda5a81ff, 0x4475e6e3, 0x0c07a888, 0x6e0703c3, "....." },
  [96895] = { "L'emissario dell'Alba d'Argento", "Trova il membro dell'⟦Argent Dawn=Alba d'Argento⟧ nei pressi dell'ingresso di ⟦Undercity=Sepulcra⟧.", "Non so se l'hai saputo, ma due emissari dell'⟦Argent Dawn=Alba d'Argento⟧ sono appena passati di qui. L'⟦Argent Dawn=Alba d'Argento⟧ non mi dispiace, ma non mi piace nemmeno che ficchino il naso a Tirisfal senza sorveglianza. Erano tutti e due Reietti... ma questo non mi rende meno nervoso.\n\nUno di loro è appena passato di qui, diretto a sud-est. In quella direzione c'è un gruppo di cultisti del Flagello che curiosa ai margini della città. Se quei due ne hanno sentito parlare, non c'è dubbio che abbiano attirato la loro attenzione.", nil, "Tieniti bass<o/a> e cerca di non farti vedere, {class}. Con questi cultisti non si scherza.", 0xdf68a7ca, 0x2508ce6f, 0x46ae3d29, nil, 0x5a1a2923, "...m." },
  [96896] = { "Una giusta causa", "Assisti alla conversazione tra Danitha Morr e Leonid Barthalomew il Reverito.", "Danitha e io abbiamo combattuto contro il Flagello in difesa di ⟦Undercity=Sepulcra⟧, quando Naxxramas ha attaccato. Quel giorno abbiamo perso molti buoni amici, compreso l'eroe da cui prende il nome questa fortezza: Garek Bandarion.\n\nForse è stato il primo Reietto a riscoprire come brandire la Luce da paladino. Mi conforta vedere la sua eredità e il suo potenziale continuare a vivere qui, con Danitha e i suoi compagni.\n\nSe solo il resto dei Reietti la pensasse allo stesso modo...", nil, "Ho intenzione di restare qui per un po' a parlare con altri amici, ma presto tornerò alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧. Se mai ti capitasse di passare da quelle parti, vieni a salutarmi. Un aiuto da avventurieri capaci ci fa sempre comodo.", 0xb14e63d6, 0x07dc792c, 0x3aaba567, nil, 0xf3a7963d, "...m." },
  [96897] = { nil, "Uccidi $N1 Dark Neophyte e $N2 Dark Enforcer nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Il Flagello è una piaga per le nostre terre, e i suoi servitori vivi sono i peggiori di tutti. La gente di Tirisfal ha già abbastanza da fare tra i morti senza mente e la ⟦Scarlet Crusade=Crociata Scarlatta⟧. Se vuoi fare del bene, aiutami a farla finita con questa feccia.", nil, "Grazie per il tuo aiuto, {class}. Se non vogliamo che la storia di Lordaeron si ripeta, dobbiamo restare vigili quando spuntano minacce come questa.", 0xb7d2480d, 0x5e8b58f6, 0xcef83677, nil, 0x346b816b, "e..m." },
  [96898] = { "Resti della guerra", "Raccogli $N1 Necrotic Crystal Fragment nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Non molto tempo fa la cittadella di Naxxramas incombeva su questa città, decisa a cancellare i Reietti dalla faccia della terra. Sia i Reietti sia l'⟦Argent Dawn=Alba d'Argento⟧ persero molto, quel giorno, per assicurare il futuro dei Reietti.\n\nDurante la battaglia, il grande cristallo focalizzatore necrotico montato in cima a Naxxramas andò in frantumi e i suoi frammenti si sparsero per tutta questa zona. Sospetto che i cultisti siano qui proprio per questo. Aiutami a recuperare i frammenti e a sottrarli al Flagello.", "Ti consiglio di non toccare troppo quei cristalli. Anche frantumati ed esauriti, la magia residua di questi cristalli necrotici è molto pericolosa.", "Grazie. Questo dovrebbe rallentare gli sforzi del Flagello in questa zona. Sospetto che gli abitanti di Tirisfal continueranno a tirare fuori questi cristalli dal terreno per anni, ma togliere quelli più in vista non può che aiutare.", 0x91003497, 0x26a56997, 0x244a6298, 0x408b3f9b, 0x6c97833f, "....." },
  [96899] = { nil, "Incontra Leonid Barthalomew a Bandarion Keep, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "Oggi hai fatto una gran cosa per la causa dell'⟦Argent Dawn=Alba d'Argento⟧, e te ne ringrazio. Non so quanto tu conosca la fortezza di Bandarion Keep, ma io e il mio comandante eravamo diretti laggiù per incontrare i paladini che vi risiedono. Questo prima di scoprire la presenza del Cult of the Damned.\n\nSe vuoi saperne di più sull'⟦Argent Dawn=Alba d'Argento⟧ e sulla nostra missione, cerca il mio comandante a Bandarion Keep, a nord-ovest di qui. Io resterò qui a ripulire il resto di questo pasticcio.", nil, "Questo posto è pieno di ricordi per me. Un tempo era in mano all'⟦Argent Dawn=Alba d'Argento⟧. Fu qui che ci preparammo a molte battaglie e scaramucce contro il Flagello durante la sua più recente offensiva nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.\n\nQuando ci ritirammo nelle ⟦Plaguelands=Terre Infette⟧ temevo che sarebbe andato in rovina. Il mio timore era fondato, ma sono lieto che Danitha e i suoi paladini ne abbiano ora assunto la custodia.\n\nHa perfino dato alla fortezza il nome di... un amico comune.", 0x48578fb3, 0x80cd9bdb, 0x27457914, nil, 0xaa8a0534, "e..m." },
  [96984] = { "Il cuore dello sconvolgimento", "Raccogli l'Arcane Mote nella città di Dalaran per il magus Wordeen Voidglare, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Forse non hai a cuore i nostri interessi, ma non rifiuterò un paio di mani in più. E se Dalaran cade, trascina con sé tutto quanto, compresa la tua ⟦Undercity=Sepulcra⟧.\n\nDunque il tuo benefattore vuole entrare? D'accordo. Infonderò la tua chiave perché superi le mie protezioni, così potrai entrare in città. Una volta dentro, raggiungimi alla Violet Citadel, dove è cominciato tutto. Con tutto quello che sta succedendo, il Kirin Tor sarà troppo occupato per fermarti.\n\nArraffa quello che vuoi, ma qualunque cosa accada, la nostra priorità è evitare una catastrofe.", nil, nil, 0x0ac2f4b9, 0xe3ed9b69, 0x6b205a30, nil, nil, "...mm" },
  [96986] = { "Il cavaliere delle tombe", "Sconfiggi Atrexis the Grave Knight nella città di Dalaran per Melisara, al ⟦Tarren Mill=Mulino di Tarren⟧.", "Nelle viscere della città dei maghi, a nord, si nasconde un traditore della nostra specie. Un negromante di inquietante talento. Sta radunando un esercito di non morti proprio sotto il naso del Kirin Tor.\n\nNon m'importa della sorte della città dei maghi, {name}, ma questo cavaliere delle tombe sputa in faccia a tutto ciò che noi Reietti rappresentiamo. Fallo fuori. Mostragli che nessuno è fuori dalla portata della Dama Oscura.", nil, nil, 0x9b982b21, 0x24bf35e3, 0x65fb9835, nil, nil, "...mm" },
  [96987] = { "Un'istruzione opportunista", "Recupera il Founding of Dalaran nella città di Dalaran per Rexxie Copperclutch, vicino all'ingresso delle fogne.", "Ma guarda, qualcuno che la pensa come me in fatto di affari. Intrufolarsi a Dalaran in tempi così burrascosi? Tsk tsk.\n\n<Un/Una> {race} come piace a me!\n\nMentre i nostri amici maghi sono occupati, magari potremmo trovarci qualche tesoro «smarrito». Hanno intere biblioteche dedicate alle loro raffinate magie arcane. Se mi porti uno dei loro tomi segreti, potrei rivenderlo a peso d'oro. E dividiamo i profitti.\n\nEhi, ehi, non guardarmi così. Neanche tu sei qui in gita scolastica. Ci stai o no?", nil, nil, 0xcb4d2d84, 0xc41dad65, 0x159f4617, nil, nil, "...mm" },
  [96988] = { "Fonte di potere", "Raccogli $N1 Cracked Sentry Core nella città di Dalaran per il dottor Martin Felben, a ⟦Undercity=Sepulcra⟧.", "Con la città di Dalaran assediata dai suoi stessi costrutti, è l'occasione perfetta per, diciamo, prendere in prestito qualche campione.\n\nImmagina un esercito di abomini alimentati dall'arcano. La Dama Oscura non avrebbe altra scelta che riconoscere la mia abilità alchemica. Magari mi metterebbe perfino a capo della Royal Apothecary Society?\n\nVa' in città e trova i nuclei dei costrutti. Difficilmente te li daranno di loro spontanea volontà, quindi fa' ciò che devi.", nil, nil, 0x64b20fc1, 0x8337ed29, 0xa537f845, nil, nil, "...mm" },
})
